1	// Official entry point for evidence runs of the SignalScout pipelines.
2	//
3	//   npx tsx scripts/run-pipeline.ts --pipeline baseline
4	//   npx tsx scripts/run-pipeline.ts --pipeline improved --llm real --confirm-spend
5	//   npx tsx scripts/run-pipeline.ts --pipeline improved --provider crustdata --confirm-spend
6	//
7	// Options: --pipeline baseline|improved, --llm fake|real (default fake),
8	// --provider fixture|crustdata (default fixture), --confirm-spend (required
9	// with --llm real or --provider crustdata), --label <string> (default:
10	// pipeline name), --config dev|eval (default eval), --trace on|off (fixture
11	// only; crustdata runs are never traced), and for crustdata runs --industry
12	// (default "Staffing and Recruiting"), --country (default "India") and
13	// --sizes (default "11-50,51-200"). CRUSTDATA_API_KEY must be set for crustdata.
14	//
15	// Writes runs/<timestamp>-<label>.json with counts, ids, costs, issue codes,
16	// tokens and timings only: no company records, keys or headers.
17	
18	import { mkdir, writeFile } from "node:fs/promises";
19	import {
20	  FakeLlmClient,
21	  type LlmClient,
22	  type LlmRequest,
23	  type LlmResponse,
24	  type PipelineResult,
25	  PROMPT_SAFETY_RULES,
26	  PROMPT_VERSION,
27	  type PipelineTracer,
28	  computeBaselineCitationMetrics,
29	  describeIcp,
30	  noopTracer,
31	  runBaselinePipeline,
32	  runImprovedPipeline,
33	} from "../src/core/agent";
34	import { createGatewayLlmClient } from "../src/core/agent/gateway-client";
35	import { CrustdataProvider } from "../src/core/data/crustdata-provider";
36	import { FixtureProvider } from "../src/core/data/fixture-provider";
37	import { BudgetGuard, type CompanyProvider } from "../src/core/data/provider";
38	import { validateCompanies } from "../src/core/data/validation";
39	import {
40	  DEFAULT_RUN_CONFIG,
41	  DEV_RUN_CONFIG,
42	  type RawCompany,
43	  type RunConfig,
44	} from "../src/core/types";
45	import {
46	  type FinalValidation,
47	  type PostHocValidation,
48	  type ResolvedRun,
49	  buildRunIcp,
50	  exitCodeForError,
51	  exitCodeForStatus,
52	  formatOutreachLine,
53	  parseRunArgs,
54	  recordSystemHashes,
55	  sha256Hex,
56	  summarizeFinalValidation,
57	  summarizeGuardFindings,
58	  summarizeOutreachKept,
59	  summarizeValidation,
60	  UsageError,
61	  validateRunArgs,
62	} from "./run-metrics";
63	
64	// What the evidence ICP means in words; matches describeIcp for the open ICP.
65	const EVIDENCE_ICP_DESCRIPTION = "Companies in any industry of any size in any location.";
66	
67	// Simulated at measured Crustdata prices (USD per record).
68	const SIMULATED_COST_PER_RECORD = { search: 0.069, enrich: 0.6 } as const;
69	
70	const EVAL_RUN_CONFIG: RunConfig = {
71	  ...DEFAULT_RUN_CONFIG,
72	  max_search_results: 10,
73	  max_enrichments: 5,
74	};
75	
76	// Both pipelines see the same records: Crustdata's default order is not stable
77	// between calls, so crustdata runs sort by company id.
78	const CRUSTDATA_SEARCH_SORT = { field: "crustdata_company_id", order: "asc" } as const;
79	
80	type Args = ResolvedRun;
81	
82	function buildLlm(kind: Args["llm"]): LlmClient {
83	  if (kind === "fake") return new FakeLlmClient();
84	  const apiKey = process.env.LITELLM_API_KEY;
85	  if (apiKey === undefined || apiKey.trim() === "") {
86	    throw new UsageError("LITELLM_API_KEY is not set; it is required for --llm real.");
87	  }
88	  return createGatewayLlmClient({ apiKey });
89	}
90	
91	// Fake-client token counts are made up; only real gateway usage is measured.
92	function tokenBasis(kind: Args["llm"]): "simulated" | "measured" {
93	  return kind === "fake" ? "simulated" : "measured";
94	}
95	
96	function fileSafe(label: string): string {
97	  return label.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "run";
98	}
99	
100	// Delegates to the real or fake client and records only the hashes of the
101	// system messages it is asked to send, never their text.
102	class HashingLlmClient implements LlmClient {
103	  readonly system_hashes = new Set<string>();
104	
105	  constructor(private readonly inner: LlmClient) {}
106	
107	  get records_llm_spans(): boolean {
108	    return this.inner.records_llm_spans;
109	  }
110	
111	  complete(request: LlmRequest): Promise<LlmResponse> {
112	    recordSystemHashes(request.messages, this.system_hashes);
113	    return this.inner.complete(request);
114	  }
115	}
116	
117	function postHocValidation(searched: readonly RawCompany[], result: PipelineResult): PostHocValidation {
118	  // The pipeline returns one prospect per searched company, in search order.
119	  return summarizeValidation(
120	    validateCompanies(searched),
121	    result.prospects.map((p) => ({
122	      company_id: p.raw.crustdata_company_id,
123	      enriched: p.enrichment.status === "enriched",
124	      delivered: p.assessment.status === "assessed",
125	    })),
126	  );
127	}
128	
129	// Validates the records as the pipeline delivered them (enriched where
130	// enriched), in result order, and compares with the search-stage verdicts.
131	function finalValidation(searched: readonly RawCompany[], result: PipelineResult): FinalValidation {
132	  return summarizeFinalValidation(
133	    validateCompanies(searched),
134	    validateCompanies(result.prospects.map((p) => p.raw)),
135	    result.prospects.map((p) => ({
136	      company_id: p.raw.crustdata_company_id,
137	      assessed: p.assessment.status === "assessed",
138	    })),
139	  );
140	}
141	
142	interface ProviderSpend {
143	  search: number;
144	  enrich: number;
145	}
146	
147	function buildReport(
148	  args: Args,
149	  config: RunConfig,
150	  icp_description: string,
151	  result: PipelineResult,
152	  started_at: string,
153	  prompt: { readonly system_prompt_hashes: readonly string[] },
154	  validation: PostHocValidation,
155	  final_validation: FinalValidation,
156	  spend: ProviderSpend,
157	) {
158	  const { run, usage } = result;
159	  const fact_provider = args.provider;
160	  const simulated = args.provider === "fixture";
161	  return {
162	    started_at,
163	    label: args.label,
164	    pipeline: args.pipeline,
165	    provider: args.provider,
166	    fact_provider,
167	    tracing: args.tracing ? "on" : "off",
168	    search_sort: simulated ? null : CRUSTDATA_SEARCH_SORT,
169	    icp_description,
170	    // ICP parameters from the flags; no company data.
171	    icp_flags: simulated ? null : { industry: args.industry, country: args.country, sizes: args.sizes },
172	    config_name: args.config,
173	    config,
174	    trace_id: run.trace_id,
175	    status: result.status,
176	    counts: run.counts,
177	    cost_usd_by_step: run.cost_usd_by_step,
178	    timings_ms_by_step: run.timings_ms_by_step,
179	    cost_basis: {
180	      provider: simulated ? "simulated" : "measured",
181	      ...(simulated && { provider_cost_per_record_usd: SIMULATED_COST_PER_RECORD }),
182	      provider_cost_usd: { search: spend.search, enrich: spend.enrich, total: spend.search + spend.enrich },
183	      llm_calls_by_basis: usage.llm_cost.calls_by_basis,
184	    },
185	    provider_usage: usage.provider,
186	    llm: {
187	      mode: args.llm,
188	      token_basis: tokenBasis(args.llm),
189	      calls: usage.llm_calls,
190	      http_attempts: usage.llm_http_attempts,
191	      input_tokens: run.counts.llm_input_tokens,
192	      output_tokens: run.counts.llm_output_tokens,
193	      gateway_reported_usd: usage.llm_cost.gateway_reported_usd,
194	      estimated_usd: usage.llm_cost.estimated_usd,
195	      known_usd: usage.llm_cost.known_usd,
196	      cost_complete: usage.llm_cost.complete,
197	    },
198	    prompt_provenance: {
199	      prompt_version: PROMPT_VERSION,
200	      prompt_safety_rules_sha256: sha256Hex(PROMPT_SAFETY_RULES),
201	      system_prompt_hashes: prompt.system_prompt_hashes,
202	    },
203	    post_hoc_validation: validation,
204	    // Both pipelines: the delivered (post-enrichment) records, validated in
205	    // memory. Codes, field names, counts and company ids only.
206	    final_record_validation: final_validation,
207	    // Both pipelines: the final outreach drafts, measured after the fact with
208	    // the same function (for improved, the drafts that survived the guards).
209	    outreach_kept: summarizeOutreachKept(result.prospects),
210	    citation_metrics: computeBaselineCitationMetrics(result, fact_provider),
211	    // Improved only: its own guardrail counts (null when it stopped before
212	    // validation) and findings by code. Counts and ids only.
213	    improved_metrics: args.pipeline === "improved" ? (result.metrics ?? null) : null,
214	    guard_findings: args.pipeline === "improved" ? summarizeGuardFindings(result.prospects, result.metrics) : null,
215	    issue_codes: result.issues.map((i) => i.code),
216	    company_ids: result.prospects.map((p) => p.raw.crustdata_company_id),
217	    prospects: result.prospects.map((p) => ({
218	      company_id: p.raw.crustdata_company_id,
219	      enrichment: p.enrichment.status,
220	      assessment: p.assessment.status,
221	      llm_call_number: p.llm_call?.call_number ?? null,
222	    })),
223	  };
224	}
225	
226	function buildProvider(args: Args, config: RunConfig): CompanyProvider & { readonly budget: BudgetGuard } {
227	  if (args.provider === "fixture") {
228	    return new FixtureProvider({ config, cost_per_record: SIMULATED_COST_PER_RECORD });
229	  }
230	  // Presence was checked by validateRunArgs before anything was built.
231	  return new CrustdataProvider({
232	    api_key: process.env.CRUSTDATA_API_KEY ?? "",
233	    budget: new BudgetGuard(config),
234	    search_sort: CRUSTDATA_SEARCH_SORT,
235	  });
236	}
237	
238	// Tracing is loaded lazily so a crustdata or --trace off run never imports or
239	// initialises neatlogs.
240	async function withTracing<T>(
241	  args: Args,
242	  fn: (tracer: PipelineTracer) => Promise<T>,
243	): Promise<T> {
244	  if (!args.tracing) return fn(noopTracer);
245	  const { span } = await import("neatlogs");
246	  const { neatlogsTracer } = await import("../src/core/agent/neatlogs-tracer");
247	  const { closeTracing, initTracing } = await import("../src/core/observability/tracing");
248	  await initTracing({ run_label: args.label });
249	  try {
250	    return await span({ kind: "WORKFLOW", name: "signalscout_run" }, () => fn(neatlogsTracer))();
251	  } finally {
252	    await closeTracing();
253	  }
254	}
255	
256	async function main(): Promise<void> {
257	  const args = validateRunArgs(parseRunArgs(process.argv.slice(2)), process.env);
258	  const config = args.config === "dev" ? DEV_RUN_CONFIG : EVAL_RUN_CONFIG;
259	  const icp = buildRunIcp(args);
260	  const icp_description =
261	    args.provider === "fixture" ? EVIDENCE_ICP_DESCRIPTION : describeIcp(icp);
262	
263	  const provider = buildProvider(args, config);
264	  const llm = new HashingLlmClient(buildLlm(args.llm));
265	  const searched: RawCompany[] = [];
266	  const spend: ProviderSpend = { search: 0, enrich: 0 };
267	  const recordingProvider: CompanyProvider = {
268	    autocompleteIndustry: (query) => provider.autocompleteIndustry(query),
269	    async enrichCompanies(urls) {
270	      const res = await provider.enrichCompanies(urls);
271	      if (res.ok) spend.enrich += res.cost_usd;
272	      return res;
273	    },
274	    async searchCompanies(filters, limit) {
275	      const res = await provider.searchCompanies(filters, limit);
276	      if (res.ok) {
277	        searched.push(...res.data);
278	        spend.search += res.cost_usd;
279	      }
280	      return res;
281	    },
282	  };
283	  const started_at = new Date().toISOString();
284	
285	  const result = await withTracing(args, (tracer) => {
286	    const deps = { provider: recordingProvider, budget: provider.budget, llm, tracer };
287	    return args.pipeline === "baseline"
288	      ? runBaselinePipeline(icp, deps, { config })
289	      : runImprovedPipeline(icp, { ...deps, fact_provider: args.provider }, { config });
290	  });
291	
292	  const system_prompt_hashes = [...llm.system_hashes].sort();
293	  const validation = postHocValidation(searched, result);
294	  const finalVal = finalValidation(searched, result);
295	  const report = buildReport(args, config, icp_description, result, started_at, { system_prompt_hashes }, validation, finalVal, spend);
296	  await mkdir("runs", { recursive: true });
297	  const path = `runs/${started_at.replace(/[:.]/g, "-")}-${fileSafe(args.label)}.json`;
298	  await writeFile(path, `${JSON.stringify(report, null, 2)}\n`);
299	
300	  const { counts, cost_usd_by_step: cost } = result.run;
301	  const llmCost = result.usage.llm_cost;
302	  const costBasis = args.provider === "fixture" ? "simulated at measured Crustdata prices" : "measured";
303	  console.log(`run ${result.run.trace_id}  status=${result.status}  label=${args.label}`);
304	  console.log(
305	    `setup    pipeline=${args.pipeline} provider=${args.provider} fact_provider=${args.provider} tracing=${args.tracing ? "on" : "off"}` +
306	      ` search_sort=${args.provider === "fixture" ? "none" : `${CRUSTDATA_SEARCH_SORT.field} ${CRUSTDATA_SEARCH_SORT.order}`}`,
307	  );
308	  console.log(
309	    `counts   searched=${counts.searched} enriched=${counts.enriched} delivered=${counts.delivered} llm_calls=${counts.llm_calls}`,
310	  );
311	  console.log(`tokens   in=${counts.llm_input_tokens} out=${counts.llm_output_tokens}  (${tokenBasis(args.llm)})`);
312	  console.log(
313	    `provider search=$${cost.search.toFixed(3)} enrich=$${cost.enrich.toFixed(3)}  (${costBasis}; provider-returned total=$${(spend.search + spend.enrich).toFixed(3)})`,
314	  );
