1	// Live-mode configuration. The environment is read in exactly one function
2	// (readLiveConfig) and values are passed explicitly from there. Results name
3	// missing variables, never their values.
4	
5	import { PgLiveStore, type PgDb } from "./pg-store";
6	
7	export interface LiveKeys {
8	  readonly crustdataApiKey: string;
9	  readonly llmApiKey: string;
10	  readonly llmBaseUrl: string;
11	}
12	
13	export interface LiveConfig {
14	  readonly databaseUrl: string;
15	  readonly hmacSecret: string;
16	  // null when any live-mode key is missing: synthetic codes still work.
17	  readonly live: LiveKeys | null;
18	  // Names only.
19	  readonly missingLiveKeys: readonly string[];
20	}
21	
22	export type LiveConfigResult =
23	  | { readonly ok: true; readonly config: LiveConfig }
24	  | { readonly ok: false; readonly missing: readonly string[] };
25	
26	type Env = Readonly<Record<string, string | undefined>>;
27	
28	function present(value: string | undefined): value is string {
29	  return typeof value === "string" && value.trim() !== "";
30	}
31	
32	export function readLiveConfig(env: Env = process.env): LiveConfigResult {
33	  const databaseUrl = env.DATABASE_URL;
34	  const hmacSecret = env.INVITE_HMAC_SECRET;
35	  const crustdataApiKey = env.CRUSTDATA_LIVE_API_KEY;
36	  const llmApiKey = env.LIVE_LLM_API_KEY;
37	  const llmBaseUrl = env.LIVE_LLM_BASE_URL;
38	
39	  const missing: string[] = [];
40	  if (!present(databaseUrl)) missing.push("DATABASE_URL");
41	  if (!present(hmacSecret)) missing.push("INVITE_HMAC_SECRET");
42	  if (!present(databaseUrl) || !present(hmacSecret)) return { ok: false, missing };
43	
44	  const missingLiveKeys: string[] = [];
45	  if (!present(crustdataApiKey)) missingLiveKeys.push("CRUSTDATA_LIVE_API_KEY");
46	  if (!present(llmApiKey)) missingLiveKeys.push("LIVE_LLM_API_KEY");
47	  if (!present(llmBaseUrl)) missingLiveKeys.push("LIVE_LLM_BASE_URL");
48	
49	  const live =
50	    present(crustdataApiKey) && present(llmApiKey) && present(llmBaseUrl)
51	      ? { crustdataApiKey, llmApiKey, llmBaseUrl }
52	      : null;
53	  return { ok: true, config: { databaseUrl, hmacSecret, live, missingLiveKeys } };
54	}
55	
56	// Serverless-sized pool. The managed database may need several seconds to
57	// wake up, hence the 10 s connection timeout. pg is imported lazily so unit
58	// tests never load it. Not called by any test.
59	export async function connectStore(
60	  databaseUrl: string,
61	): Promise<{ store: PgLiveStore; close(): Promise<void> }> {
62	  const { Pool } = await import("pg");
63	  const pool = new Pool({
64	    connectionString: databaseUrl,
65	    max: 3,
66	    connectionTimeoutMillis: 10_000,
67	    idleTimeoutMillis: 10_000,
68	  });
69	  const db: PgDb = {
70	    query: (text, params) => pool.query(text, params),
71	    async transaction(fn) {
72	      const client = await pool.connect();
73	      try {
74	        await client.query("BEGIN");
75	        const out = await fn({ query: (t, p) => client.query(t, p) });
76	        await client.query("COMMIT");
77	        return out;
78	      } catch (err) {
79	        await client.query("ROLLBACK").catch(() => undefined);
80	        throw err;
81	      } finally {
82	        client.release();
83	      }
84	    },
85	  };
86	  return { store: new PgLiveStore(db), close: () => pool.end() };
87	}
