1	// Live-mode orchestration: one request in, one typed { httpStatus, body } out.
2	// Order: validate, rate limit, reserve a run, check the kill switch (live
3	// codes only), then run in the mode the code is bound to. Fails closed. Never logs. Bodies carry fixed
4	// messages only: no keys, codes, upstream text, stack traces or company data.
5	
6	import type { LlmClient } from "../../core/agent/llm";
7	import { runImprovedPipeline } from "../../core/agent/improved-pipeline";
8	import type { CheckResult, IcpInput, PipelineResult } from "../../core/agent/types";
9	import { BudgetGuard, type BudgetSnapshot, type CompanyProvider } from "../../core/data/provider";
10	import { DEFAULT_RUN_CONFIG, type RunConfig, type Validation } from "../../core/types";
11	import {
12	  type SyntheticDependencies,
13	  runSyntheticPipeline,
14	  syntheticDependencies,
15	} from "../../app/results/_lib/synthetic-run";
16	import { hashCode, hashIp } from "./codes";
17	import type { LiveKeys } from "./config";
18	import { type CodeMode, type LiveStore, type RunOutcome } from "./store";
19	import { type ValidRequest, validateRequest } from "./validate";
20	
21	const IP_WINDOW_SECONDS = 60;
22	const IP_LIMIT = 20;
23	const BAD_CODE_WINDOW_SECONDS = 900;
24	const BAD_CODE_LIMIT = 5;
25	const RUN_LOCK_SECONDS = 330;
26	
27	export const LIVE_RUN_CONFIG: RunConfig = {
28	  ...DEFAULT_RUN_CONFIG,
29	  max_search_results: 10,
30	  max_enrichments: 5,
31	  model: "claude-haiku",
32	  max_llm_calls_per_run: 20,
33	  max_output_tokens_per_call: 1500,
34	};
35	
36	export const LIVE_SEARCH_SORT = { field: "crustdata_company_id", order: "asc" } as const;
37	
38	export const SYNTHETIC_NOTICES: readonly string[] = [
39	  "Synthetic demo: fixture companies and a fake model; your search criteria were not used.",
40	  "One outreach draft deliberately contains an injected unsupported number so you can see the claim check suppress it.",
41	];
42	
43	// ---- Response contract ----------------------------------------------------
44	
45	// What the injected mapper returns is opaque here. The mapper owns the shape
46	// of the results and must not copy upstream text into them.
47	export interface ResultsContext {
48	  readonly mode: CodeMode;
49	  readonly model: string;
50	}
51	
52	export type ToResults = (result: PipelineResult, ctx: ResultsContext) => unknown;
53	
54	export type LiveBody =
55	  | {
56	      readonly status: "ok";
57	      readonly mode: CodeMode;
58	      readonly results: unknown;
59	      readonly usage: { readonly runsRemaining: number };
60	      readonly notices: readonly string[];
61	    }
62	  | { readonly status: "invalid_request"; readonly field: string; readonly message: string }
63	  | { readonly status: "rate_limited"; readonly retryAfterSeconds: number; readonly message: string }
64	  | { readonly status: "live_disabled"; readonly message: string }
65	  | { readonly status: "invalid_code"; readonly message: string }
66	  | { readonly status: "no_runs_left"; readonly message: string }
67	  | { readonly status: "run_in_progress"; readonly message: string }
68	  | { readonly status: "budget_exhausted"; readonly message: string }
69	  | { readonly status: "run_failed"; readonly message: string }
70	  | { readonly status: "live_unavailable"; readonly message: string };
71	
72	export interface LiveOutcome {
73	  readonly httpStatus: 200 | 400 | 401 | 403 | 409 | 429 | 502 | 503;
74	  readonly body: LiveBody;
75	}
76	
77	const MESSAGES = {
78	  live_disabled: "Live runs are switched off right now.",
79	  invalid_code: "That invite code is not valid.",
80	  no_runs_left: "This invite code has no runs left.",
81	  run_in_progress: "A run is already in progress for this code. Try again shortly.",
82	  budget_exhausted: "The data budget for live runs is used up. Please try again later.",
83	  run_failed: "The run failed. Please try again later.",
84	  live_unavailable: "Live mode is unavailable right now. Please try again later.",
85	  rate_limited: "Too many requests. Please wait before trying again.",
86	  industry_unmatched: "We could not match that industry. Try a broader term.",
87	} as const;
88	
89	const ISSUE_NOTICES: Readonly<Record<string, string | undefined>> = {
90	  enrich_partial: "Some companies could not be enriched, so those use basic search data only.",
91	  enrich_no_results: "No companies could be enriched, so results use basic search data only.",
92	  enrich_failed: "Enrichment failed, so results use basic search data only.",
93	  enrich_budget_exhausted: "The enrichment budget was reached before every company was enriched.",
94	  search_no_match: "No companies matched your criteria.",
95	  search_budget_exhausted: "The search budget was reached.",
96	  llm_call_cap_reached: "The model-call limit was reached, so some companies were not assessed.",
97	  llm_stopped: "Assessment stopped early after a model error, so some companies were not assessed.",
98	  llm_cost_incomplete: "Model cost for this run could not be fully measured.",
99	};
100	
101	const GENERIC_ISSUE_MESSAGE = "A step of the run reported a problem.";
102	
103	const FAILED_ASSESSMENT_MESSAGES: Readonly<Record<string, string | undefined>> = {
104	  llm_error: "The model could not assess this company.",
105	  malformed_output: "The model's answer could not be read.",
106	  truncated: "The model's answer was cut off.",
107	  invalid_assessment: "The model's assessment failed the checks.",
108	};
109	const GENERIC_ASSESSMENT_MESSAGE = "The assessment failed.";
110	
111	const VALIDATION_REASONS: Readonly<Record<string, string | undefined>> = {
112	  missing_name: "The company has no name.",
113	  missing_domain: "The company has no primary domain.",
114	  junk_website: "The website is not a company site.",
115	  duplicate_domain: "The company duplicates another result.",
116	  size_headcount_mismatch: "The size range and headcount disagree.",
117	  missing_linkedin: "The company has no LinkedIn page.",
118	};
119	const GENERIC_VALIDATION_REASON = "The company failed a data check.";
120	const GENERIC_FINDING_MESSAGE = "The assessment failed a check.";
121	const FINDING_MESSAGES: Readonly<Record<string, string | undefined>> = {
122	  fit_score_out_of_range: "The fit score is outside 0-100.",
123	  criterion_score_out_of_range: "A criterion score is outside 0-100.",
124	  missing_criterion: "A requested criterion was not scored.",
125	  unexpected_criterion: "A criterion was scored that was not requested.",
126	  duplicate_criterion: "A criterion was scored more than once.",
127	  unknown_fact_reference: "A score references an unknown fact.",
128	  uncertain_fact_reference: "A score references an uncertain fact.",
129	  no_citations: "The outreach cites no facts.",
130	  duplicate_citation: "The outreach cites a fact more than once.",
131	  unknown_citation: "The outreach cites an unknown fact.",
132	  model_fact_citation: "The outreach cites a model-written fact.",
133	  non_citeable_citation: "The outreach cites a fact that cannot be cited.",
134	  unsupported_number: "The outreach states a number no cited fact supports.",
135	};
136	
137	function scrubValidation(v: Validation | undefined): Validation | undefined {
138	  if (v === undefined) return v;
139	  return {
140	    ...v,
141	    issues: v.issues.map((i) => ({ ...i, reason: VALIDATION_REASONS[i.code] ?? GENERIC_VALIDATION_REASON })),
142	  };
143	}
144	
145	function scrubCheck(c: CheckResult): CheckResult {
146	  return {
147	    ...c,
148	    findings: c.findings.map(({ code, severity }) => ({
149	      code,
150	      severity,
151	      message: FINDING_MESSAGES[code] ?? GENERIC_FINDING_MESSAGE,
152	    })),
153	  };
154	}
155	
156	// Returns a copy of the pipeline result in which every free-text field that
157	// can carry upstream, model-error or user text is replaced by a fixed string
158	// chosen by its code or reason. Never mutates its input. Company data, facts
159	// and model assessments are the payload and pass through unchanged.
160	export function scrubResult(result: PipelineResult): PipelineResult {
161	  return {
162	    ...result,
163	    run: { ...result.run, input_description: "Run criteria withheld." },
164	    issues: result.issues.map((i) => ({ ...i, message: ISSUE_NOTICES[i.code] ?? GENERIC_ISSUE_MESSAGE })),
165	    prospects: result.prospects.map((p) => {
166	      const assessment =
167	        p.assessment.status === "failed"
168	          ? {
169	              ...p.assessment,
170	              message: FAILED_ASSESSMENT_MESSAGES[p.assessment.reason] ?? GENERIC_ASSESSMENT_MESSAGE,
171	            }
172	          : p.assessment;
173	      const scrubbed = { ...p, assessment };
174	      const search_validation = scrubValidation(p.search_validation);
175	      const validation = scrubValidation(p.validation);
176	      return {
177	        ...scrubbed,
178	        ...(search_validation !== undefined ? { search_validation } : {}),
179	        ...(validation !== undefined ? { validation } : {}),
180	        ...(p.checks !== undefined
181	          ? {
182	              checks: {
183	                ...p.checks,
184	                assessment: scrubCheck(p.checks.assessment),
185	                ...(p.checks.claims !== undefined ? { claims: scrubCheck(p.checks.claims) } : {}),
186	              },
187	            }
188	          : {}),
189	      };
190	    }),
191	  };
192	}
193	
194	function respond(httpStatus: LiveOutcome["httpStatus"], body: LiveBody): LiveOutcome {
195	  return { httpStatus, body };
196	}
197	
198	const simple = (
199	  httpStatus: LiveOutcome["httpStatus"],
200	  status:
201	    | "live_disabled"
202	    | "invalid_code"
203	    | "no_runs_left"
204	    | "run_in_progress"
205	    | "budget_exhausted"
206	    | "run_failed"
207	    | "live_unavailable",
208	): LiveOutcome => respond(httpStatus, { status, message: MESSAGES[status] });
209	
210	// For callers that fail before runLive (e.g. configuration is missing).
211	export const liveUnavailable = (): LiveOutcome => simple(503, "live_unavailable");
212	
213	function rateLimited(retryAfterSeconds: number): LiveOutcome {
214	  const seconds = Number.isFinite(retryAfterSeconds) ? Math.max(1, Math.ceil(retryAfterSeconds)) : 60;
215	  return respond(429, { status: "rate_limited", retryAfterSeconds: seconds, message: MESSAGES.rate_limited });
216	}
217	
218	function noticesFromIssues(issues: readonly { readonly code: string }[]): string[] {
219	  const out: string[] = [];
220	  for (const issue of issues) {
221	    const text = ISSUE_NOTICES[issue.code];
222	    if (text !== undefined && !out.includes(text)) out.push(text);
223	  }
224	  return out;
225	}
226	
227	// ---- Dependencies -----------------------------------------------------------
228	
229	export interface LiveProviderBundle {
230	  readonly provider: CompanyProvider;
231	  readonly budget: { snapshot(): BudgetSnapshot };
232	}
233	
234	export interface LiveDeps {
235	  readonly store: LiveStore;
236	  readonly hmacSecret: string;
237	  // null when live keys are not configured: synthetic codes still run.
238	  readonly live: LiveKeys | null;
239	  readonly now: () => Date;
240	  // Live factories. Never called in synthetic mode.
241	  readonly createProvider: (keys: LiveKeys, config: RunConfig) => LiveProviderBundle | Promise<LiveProviderBundle>;
242	  readonly createLlm: (keys: LiveKeys) => LlmClient | Promise<LlmClient>;
243	  readonly synthetic?: SyntheticDependencies;
244	  // Builds the 200 body's results for both modes.
245	  readonly toResults: ToResults;
246	}
247	
248	// The real factories. SDKs are imported lazily so synthetic runs and unit
249	// tests never load them.
250	export const realFactories: Pick<LiveDeps, "createProvider" | "createLlm"> = {
251	  async createProvider(keys, config) {
252	    const { CrustdataProvider } = await import("../../core/data/crustdata-provider");
253	    const budget = new BudgetGuard(config);
254	    const provider = new CrustdataProvider({
255	      api_key: keys.crustdataApiKey,
256	      budget,
257	      search_sort: LIVE_SEARCH_SORT,
258	    });
259	    return { provider, budget };
260	  },
261	  async createLlm(keys) {
262	    const { createGatewayLlmClient } = await import("../../core/agent/gateway-client");
263	    return createGatewayLlmClient({ apiKey: keys.llmApiKey, baseURL: keys.llmBaseUrl });
264	  },
265	};
266	
267	// ---- Orchestration ----------------------------------------------------------
268	
269	export async function runLive(
270	  request: { readonly code: unknown; readonly icp: unknown },
271	  ip: string,
272	  deps: LiveDeps,
273	): Promise<LiveOutcome> {
274	  const checked = validateRequest(request);
275	  if (!checked.ok) {
276	    return respond(400, { status: "invalid_request", field: checked.field, message: checked.message });
277	  }
278	  const valid = checked.value;
279	
280	  let reserved: Reserved;
281	  try {
282	    const { store, hmacSecret } = deps;
283	    const ipHash = hashIp(ip, hmacSecret);
284	
285	    const rate = await store.hit(`ip:${ipHash}`, deps.now(), IP_WINDOW_SECONDS, IP_LIMIT);
286	    if (!rate.allowed) return rateLimited(rate.retryAfterSeconds);
287	
288	    const result = await store.reserveRun(hashCode(valid.code, hmacSecret), deps.now(), RUN_LOCK_SECONDS);
289	    if (!result.ok) {
290	      switch (result.reason) {
291	        case "invalid_code":
292	        case "disabled": {
293	          const bad = await store.hit(`badcode:${ipHash}`, deps.now(), BAD_CODE_WINDOW_SECONDS, BAD_CODE_LIMIT);
294	          if (!bad.allowed) return rateLimited(bad.retryAfterSeconds);
295	          return simple(401, "invalid_code");
296	        }
297	        case "no_runs_left":
298	          return simple(403, "no_runs_left");
299	        case "run_in_progress":
300	          return simple(409, "run_in_progress");
301	        default:
302	          return simple(503, "live_unavailable");
303	      }
304	    }
305	    reserved = { runId: result.runId, runsRemaining: result.runsRemaining, mode: result.mode };
306	  } catch {
307	    return simple(503, "live_unavailable");
308	  }
309	
310	  // From here a run exists: every exit must finish or release it.
311	  const { store } = deps;
312	
313	  // The kill switch only stops live-mode codes; synthetic codes never read it.
314	  if (reserved.mode === "live") {
315	    // Keys missing or live not allowed by the runtime fail-safe: do not attempt the run.
316	    if (deps.live === null) {
317	      await giveBack(store, reserved.runId);
318	      return simple(503, "live_disabled");
319	    }
320	    let enabled: boolean;
321	    try {
322	      enabled = await store.isLiveEnabled();
323	    } catch {
324	      await giveBack(store, reserved.runId);
325	      return simple(503, "live_unavailable");
326	    }
327	    if (!enabled) {
328	      await giveBack(store, reserved.runId);
329	      return simple(503, "live_disabled");
330	    }
331	  }
332	
333	  const settle = async (op: () => Promise<void>) => {
334	    try {
335	      await op();
336	    } catch {
337	      // The outcome is already decided; a store failure cannot change it.
338	    }
339	  };
340	  const failed = async (outcome: Partial<RunOutcome> = {}): Promise<LiveOutcome> => {
341	    await settle(() =>
342	      store.finishRun(reserved.runId, {
343	        status: "failed",
344	        searched: 0,
345	        enriched: 0,
346	        providerCostUsd: 0,
347	        modelCostUsd: 0,
348	        errorCategory: "run_failed",
349	        ...outcome,
350	      }),
351	    );
352	    return simple(502, "run_failed");
353	  };
354	
355	  try {
356	    return reserved.mode === "synthetic"
357	      ? await runSynthetic(reserved, deps, failed)
358	      : await runLiveMode(valid, reserved, deps, failed);
359	  } catch {
360	    return failed();
361	  }
362	}
363	
364	async function giveBack(store: LiveStore, runId: string): Promise<void> {
365	  try {
366	    await store.releaseRun(runId);
367	  } catch {
368	    // Nothing more can be done; the lock expires on its own.
369	  }
370	}
371	
372	// The user already has what the run produced, so a bookkeeping failure is
373	// retried once and then ignored. It is never recorded as a different status.
374	async function finishCompleted(store: LiveStore, runId: string, outcome: RunOutcome): Promise<void> {
375	  for (let attempt = 0; attempt < 2; attempt++) {
376	    try {
377	      await store.finishRun(runId, outcome);
378	      return;
379	    } catch {
380	      // Retry once, then give up.
381	    }
382	  }
383	}
384	
385	interface Reserved {
386	  readonly runId: string;
387	  readonly runsRemaining: number;
388	  readonly mode: CodeMode;
389	}
390	
391	type Failed = (outcome?: Partial<RunOutcome>) => Promise<LiveOutcome>;
392	
393	async function runSynthetic(reserved: Reserved, deps: LiveDeps, failed: Failed): Promise<LiveOutcome> {
394	  const run = await runSyntheticPipeline("synthetic", deps.synthetic ?? syntheticDependencies);
395	  if (run.kind !== "ok") return failed();
396	  const { result } = run;
397	  const searched = result.usage.provider.searched;
398	  const enriched = result.usage.provider.enriched;
399	  const results = deps.toResults(scrubResult(result), { mode: "synthetic", model: "fake" });
400	  await finishCompleted(deps.store, reserved.runId, {
401	    status: "completed",
402	    searched,
403	    enriched,
404	    providerCostUsd: 0,
405	    modelCostUsd: 0,
406	  });
407	  const notices = [...SYNTHETIC_NOTICES, ...noticesFromIssues(result.issues)];
408	  return respond(200, {
409	    status: "ok",
410	    mode: "synthetic",
411	    results,
412	    usage: { runsRemaining: reserved.runsRemaining },
413	    notices,
414	  });
415	}
416	
417	async function runLiveMode(
418	  valid: ValidRequest,
419	  reserved: Reserved,
420	  deps: LiveDeps,
421	  failed: Failed,
422	): Promise<LiveOutcome> {
423	  const { store } = deps;
424	  const release = async (): Promise<LiveOutcome> => {
425	    await giveBack(store, reserved.runId);
426	    return simple(502, "run_failed");
427	  };
428	
429	  // Before the first paid call: any failure gives the run back.
430	  let bundle: LiveProviderBundle;
431	  let llm: LlmClient;
432	  let industry: string;
433	  const notices: string[] = [];
434	  try {
435	    if (deps.live === null) return await release();
436	    bundle = await deps.createProvider(deps.live, LIVE_RUN_CONFIG);
437	    llm = await deps.createLlm(deps.live);
438	
439	    const suggestions = await bundle.provider.autocompleteIndustry(valid.icp.industry);
440	    if (!suggestions.ok && suggestions.error.category === "no_match") {
441	      await store.releaseRun(reserved.runId);
442	      return respond(400, {
443	        status: "invalid_request",
444	        field: "industry",
445	        message: MESSAGES.industry_unmatched,
446	      });
447	    }
448	    if (!suggestions.ok || suggestions.data.length === 0) return await release();
449	    industry = suggestions.data[0];
450	    notices.push(`Searched the industry "${industry.slice(0, 80)}", the closest match to what you entered.`);
451	  } catch {
452	    return release();
453	  }
454	
455	  const icp: IcpInput = {
456	    industry,
457	    employee_count_ranges: valid.icp.sizes,
458	    locations: [valid.icp.country],
459	    keywords: [],
460	    excluded_domains: [],
461	  };
462	
463	  let result: PipelineResult;
464	  try {
465	    result = await runImprovedPipeline(
466	      icp,
467	      { provider: bundle.provider, budget: bundle.budget, llm, fact_provider: "crustdata" },
468	      { config: LIVE_RUN_CONFIG },
469	    );
470	  } catch {
471	    const snap = safeSnapshot(bundle.budget);
472	    return failed({
473	      searched: snap.searched,
474	      enriched: snap.enriched,
475	      providerCostUsd: snap.cost_usd,
476	      errorCategory: "pipeline_exception",
477	    });
478	  }
479	
480	  const searched = result.usage.provider.searched;
481	  const enriched = result.usage.provider.enriched;
482	  const providerCostUsd = result.usage.provider.cost_usd;
483	  const modelCostUsd = result.usage.llm_cost.known_usd;
484	
485	  if (result.status === "stopped") {
486	    const exhausted = result.issues.some((i) => i.error_category === "budget_cap_reached");
487	    const outcome: RunOutcome = {
488	      status: exhausted ? "budget_exhausted" : "failed",
489	      searched,
490	      enriched,
491	      providerCostUsd,
492	      modelCostUsd,
493	      errorCategory: exhausted ? "budget_cap_reached" : "pipeline_stopped",
494	    };
495	    try {
496	      await store.finishRun(reserved.runId, outcome);
497	    } catch {
498	      // The response is already decided.
499	    }
